SpringDataRedis的序列化方式
我们可以自定义RedisTemplate的序列化方式，代码如下：
@Beanpublic RedisTemplate<String, Object> redisTemplate(RedisConnectionFactory redisConnectionFactory)        throws UnknownHostException {    // 创建Template    RedisTemplate<String, Object> redisTemplate = new RedisTemplate<>();    // 设置连接工厂    redisTemplate.setConnectionFactory(redisConnectionFactory);    // 设置序列化工具    GenericJackson2JsonRedisSerializer jsonRedisSerializer =
new GenericJackson2JsonRedisSerializer();
// key和 hashKey采用 string序列化    redisTemplate.setKeySerializer(RedisSerializer.string());     redisTemplate.setHashKeySerializer(RedisSerializer.string());
// value和 hashValue采用 JSON序列化    redisTemplate.setValueSerializer(jsonRedisSerializer);    redisTemplate.setHashValueSerializer(jsonRedisSerializer);    return redisTemplate;}

